Unit Title: ${unitTitle}
Unit Code: ${unitCode}
Class: ${className}
Learners: ${numLearners}
Week: ${weekNo}
Session Number: ${sessionNo}
Session Title from LP: ${lpRows.length > 0 ? lpRows[0].session_title : sessionTitle}
